  "adicionar_maquina": { pt: `Adicionar máquina`, en: `Add machine`, es: `Añadir máquina`, fr: `Ajouter une machine` },
  "localizar_maquinas_na_rede": { pt: `Localizar máquinas na rede`, en: `Find machines on network`, es: `Buscar máquinas en la red`, fr: `Trouver des machines sur le réseau` },
  "scan_boas_vindas": { pt: `👋 Bem-vindo! Ainda não tens nenhuma máquina adicionada — estamos a procurar automaticamente na tua rede local. Também podes adicionar à mão em baixo, ou fechar esta janela e procurar mais tarde no botão "Localizar máquinas na rede".`, en: `👋 Welcome! You don't have any machines added yet — we're automatically scanning your local network. You can also add one manually below, or close this window and search later using the "Find machines on network" button.`, es: `👋 ¡Bienvenido! Todavía no tienes ninguna máquina añadida — estamos buscando automáticamente en tu red local. También puedes añadir una manualmente abajo, o cerrar esta ventana y buscar más tarde con el botón "Buscar máquinas en la red".`, fr: `👋 Bienvenue ! Tu n'as encore aucune machine ajoutée — on recherche automatiquement sur ton réseau local. Tu peux aussi en ajouter une manuellement ci-dessous, ou fermer cette fenêtre et chercher plus tard avec le bouton « Trouver des machines sur le réseau ».` },
  "sub_rede_a_pesquisar": { pt: `Sub-rede a pesquisar`, en: `Subnet to search`, es: `Subred a buscar`, fr: `Sous-réseau à rechercher` },
  "pesquisar": { pt: `Pesquisar`, en: `Search`, es: `Buscar`, fr: `Rechercher` },
  "sub_rede_hint": { pt: `Se as tuas máquinas estiverem numa rede WiFi diferente da deste computador (ex: 192.168.25.x em vez de 192.168.1.x), escreve aqui os 3 primeiros números do IP delas.`, en: `If your machines are on a different WiFi network from this computer (e.g. 192.168.25.x instead of 192.168.1.x), type the first 3 numbers of their IP here.`, es: `Si tus máquinas están en una red WiFi diferente a la de este ordenador (ej: 192.168.25.x en vez de 192.168.1.x), escribe aquí los 3 primeros números de su IP.`, fr: `Si tes machines sont sur un réseau WiFi différent de cet ordinateur (ex : 192.168.25.x au lieu de 192.168.1.x), écris ici les 3 premiers chiffres de leur IP.` },
  "a_iniciar_scan": { pt: `A iniciar scan...`, en: `Starting scan...`, es: `Iniciando escaneo...`, fr: `Démarrage du scan...` },
  "a_procurar_maquinas_na_rede": { pt: `A procurar máquinas na rede local`, en: `Searching for machines on the local network`, es: `Buscando máquinas en la red local`, fr: `Recherche de machines sur le réseau local` },
  "erro_ao_procurar_maquinas_na_rede": { pt: `Não foi possível concluir o scan da rede. Confirma que o servidor local está a correr.`, en: `Could not complete the network scan. Make sure the local server is running.`, es: `No se pudo completar el escaneo de la red. Confirma que el servidor local está en ejecución.`, fr: `Impossible de terminer le scan réseau. Vérifie que le serveur local est en cours d'exécution.` },
  "nenhuma_maquina_encontrada_na_rede": { pt: `Nenhuma máquina encontrada na rede local.`, en: `No machines found on the local network.`, es: `No se encontraron máquinas en la red local.`, fr: `Aucune machine trouvée sur le réseau local.` },
  "adicionar_todas": { pt: `Adicionar todas`, en: `Add all`, es: `Añadir todas`, fr: `Tout ajouter` },
  "overclock": { pt: `🔧 OC`, en: `🔧 OC`, es: `🔧 OC`, fr: `🔧 OC` },
  "overclock_undervolt": { pt: `🔧 Overclock / Undervolt das Máquinas`, en: `🔧 Machine Overclock / Undervolt`, es: `🔧 Overclock / Undervolt de las Máquinas`, fr: `🔧 Overclock / Undervolt des Machines` },
  "oc_hint": { pt: `Ajusta a frequência (MHz) e a voltagem do núcleo (mV) de cada máquina diretamente a partir daqui. "Guardar" aplica as novas definições; "Reiniciar" reinicia a máquina para garantir que ficam ativas. Valores muito agressivos podem causar instabilidade ou sobreaquecimento — ajusta com cuidado e observa a temperatura depois de aplicar.`, en: `Adjust each machine's frequency (MHz) and core voltage (mV) directly from here. "Save" applies the new settings; "Restart" reboots the machine to make sure they take effect. Overly aggressive values can cause instability or overheating — adjust carefully and watch the temperature afterwards.`, es: `Ajusta la frecuencia (MHz) y el voltaje del núcleo (mV) de cada máquina directamente desde aquí. "Guardar" aplica los nuevos ajustes; "Reiniciar" reinicia la máquina para asegurar que se activen. Valores muy agresivos pueden causar inestabilidad o sobrecalentamiento — ajusta con cuidado y observa la temperatura después.`, fr: `Ajuste la fréquence (MHz) et la tension du cœur (mV) de chaque machine directement ici. "Enregistrer" applique les nouveaux réglages ; "Redémarrer" relance la machine pour qu'ils prennent effet. Des valeurs trop agressives peuvent causer instabilité ou surchauffe — ajuste avec précaution et surveille la température ensuite.` },
  "atual_freq": { pt: `atual:`, en: `current:`, es: `actual:`, fr: `actuel :` },
  "atual_volt": { pt: `atual:`, en: `current:`, es: `actual:`, fr: `actuel :` },
