  "layout_edicao_ativada": { pt: `Modo de edição de layout ativado - arrasta os painéis pelo canto "⠿ arrastar" para reordenar.`, en: `Layout edit mode enabled - drag panels by the "⠿ drag" corner to reorder them.`, es: `Modo de edición de diseño activado - arrastra los paneles por la esquina "⠿ arrastrar" para reordenarlos.`, fr: `Mode d'édition de la disposition activé - fais glisser les panneaux par le coin "⠿ glisser" pour les réordonner.` },
  "confirm_repor_layout": { pt: `Repor a ordem original dos painéis do Dashboard Geral?`, en: `Reset the original panel order of the General Dashboard?`, es: `¿Restablecer el orden original de los paneles del Panel General?`, fr: `Réinitialiser l'ordre original des panneaux du Tableau de bord général ?` },
